Το απόσπασμα της συνεδρίασης είναι το εξής:
[
  {
    "speakerName": "Δέσποινα Λιμνιωτάκη",
    "speakerParty": "Αθήνα Τώρα",
    "utterances": [
      {
        "text": "Θέμα 3.",
        "utteranceId": "s4hh87x3"
      },
      {
        "text": "Κυρία Ευαγγελίδου.",
        "utteranceId": "3iwg86lp"
      },
      {
        "text": "Ως η εισήγηση το 3 και το 4.",
        "utteranceId": "xhn7pfce"
      },
      {
        "text": "Έχουμε κάποια παρατήρηση εδώ;",
        "utteranceId": "886ddrc2"
      },
      {
        "text": "Ο κύριος Σοφιανός έχει παρατήρηση.",
        "utteranceId": "nzslr1za"
      }
    ]
  }
]

Η τρέχουσα λίστα subjects:
[
  {
    "id": "4gbgvy02",
    "name": "Θέση στάσης ξενοδοχείου Eternity Athens",
    "description": "Θα εξεταστεί η παραχώρηση αποκλειστικής χρήσης τμήματος εσοχής 10 μέτρων επί της οδού Μητροπόλεως 62 για το ξενοδοχείο «ETERNITY ATHENS» 70 κλινών, καθώς και η τοποθέτηση σχετικής σήμανσης. Απαιτείται απόλυτη πλειοψηφία.",
    "type": "IN_AGENDA"
  }
]
